describe('Login to Secure Area', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/login');
  });

  it('should successfully log in with valid credentials and display success message', () => {
    cy.get('#username').should('be.visible').type('tomsmith');
    cy.get('#password').should('be.visible').type('SuperSecretPassword!');
    cy.get('button[type="submit"]').should('be.visible').click();

    cy.url().should('include', '/secure');
    cy.get('.flash.success').should('be.visible').and('contain', 'You logged into a secure area!');
  });

  it('should display error message when logging in with invalid credentials', () => {
    cy.get('#username').should('be.visible').type('invaliduser');
    cy.get('#password').should('be.visible').type('wrongpassword');
    cy.get('button[type="submit"]').should('be.visible').click();

    cy.url().should('include', '/login');
    cy.get('.flash.error').should('be.visible').and('contain', 'Your username is invalid!');
  });

  it('should not submit form when username field is empty', () => {
    cy.get('#password').should('be.visible').type('SuperSecretPassword!');
    cy.get('button[type="submit"]').should('be.visible').click();

    cy.url().should('include', '/login');
    cy.get('.flash.error').should('be.visible');
  });

  it('should not submit form when password field is empty', () => {
    cy.get('#username').should('be.visible').type('tomsmith');
    cy.get('button[type="submit"]').should('be.visible').click();

    cy.url().should('include', '/login');
    cy.get('.flash.error').should('be.visible');
  });
});
